def shell(title, description, body, active='', slug='', ogimg='luxury-renovation', ishome=False):
    url=root+('/'+slug if slug else '/')
    seo={"@context":"https://schema.org","@type":"WebPage","name":title,"url":url,"description":description,"isPartOf":{"@type":"WebSite","name":"Milestone Renovate","url":root+"/"},"inLanguage":"en-AU"}
    if ishome: seo={"@context":"https://schema.org","@graph":[{"@type":"WebSite","name":"Milestone Renovate","url":root+"/"},{"@type":"Organization","name":"Milestone Renovate","url":root+"/","parentOrganization":{"@type":"Organization","name":"Milestone Development","url":parent+"/"},"contactPoint":{"@type":"ContactPoint","telephone":"+61-1800-008-883","contactType":"customer service"}},{"@type":"WebPage","name":title,"url":url,"description":description,"inLanguage":"en-AU"}]}
    return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#193b32"><title>{escape(title)}</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{url}"><link rel="icon" href="/assets/favicon.png" type="image/png"><meta property="og:locale" content="en_AU"><meta property="og:type" content="website"><meta property="og:site_name" content="Milestone Renovate"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{imgs[ogimg]}"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="/css/site.css"><script type="application/ld+json">{json.dumps(seo)}</script><script defer src="/js/site.js"></script></head><body>{header(active)}<main id="content">{body}</main>{footer()}</body></html>'''

def kicker(s): return f'<p class="eyebrow">{s}</p>'

def split_header(k, title, desc):return f'<div class="section-header"><div>{kicker(k)}<h2>{title}</h2></div><p>{desc}</p></div>'

def cta(): return '''<section class="cta-strip"><div class="wrap cta-grid"><div><p class="eyebrow inverse">PLAN YOUR RENOVATION</p><h2>Have a space in mind?<br><em>Let’s explore the possibilities.</em></h2></div><div><p>Tell us what you’re planning. We’ll help you work through the first practical steps.</p><a class="btn btn-cream" href="/contact">Request a conversation <span>↗</span></a></div></div></section>'''

home=f'''<section class="hero"><div class="hero-photo">{picture('luxury-renovation','Architectural interior renovation concept with warm finishes','hero-image','eager')}</div><div class="hero-shade"></div><div class="wrap hero-content">{kicker('THE RENOVATION CHAPTER OF MILESTONE')}<h1>Space to live.<br><em>Room to become.</em></h1><p>From the first idea to the final detail, we approach home renovations with clear thinking, considered design and an appreciation for how you live.</p><div class="hero-buttons"><a class="btn btn-cream" href="/contact">Plan your renovation <span>↗</span></a><a class="text-link light" href="/services">Explore our services <span>↗</span></a></div></div><div class="hero-caption">01 / RENOVATION-LED THINKING <span>SYDNEY • NSW</span></div></section>
<section class="ticker"><div class="wrap ticker-inner"><span>CONSIDERED DESIGN</span><i></i><span>SMARTER SPACES</span><i></i><span>QUALITY-FOCUSED DETAIL</span><i></i><span>BUILDER-LED PERSPECTIVE</span></div></section>
<section class="section intro"><div class="wrap intro-grid"><div>{kicker('A HOME, REIMAGINED')}<h2>Not a new address.<br><em>A new perspective.</em></h2></div><div><p class="lead">Sometimes the home you love simply needs to evolve with you.</p><p>Milestone Renovate is a renovation-focused sister brand of Milestone Development. We bring the same thoughtful approach to planning and delivery into existing homes — reworking spaces, reconsidering layouts and elevating everyday living.</p><a class="text-link" href="/about">Discover our approach <span>↗</span></a></div></div></section>
<section class="section services-surface"><div class="wrap">{split_header('WHAT WE DO','Every space has <em>possibility.</em>','From one considered room to a home-wide transformation, start with what matters most to you.')}<div class="service-grid"><a class="service-tile featured" href="/home-renovations">{picture('featured-luxury-home','Illustrative architectural home renovation design')}<div class="tile-overlay"><span class="service-number">01 / WHOLE HOME</span><h3>Whole-home<br>renovations</h3><span class="circle-arrow">↗</span></div></a><a class="service-tile" href="/kitchen-renovations">{picture('luxury-renovation','Illustrative contemporary open-plan kitchen and living design')}<div class="tile-overlay"><span class="service-number">02 / KITCHENS</span><h3>Kitchen<br>renovations</h3><span class="circle-arrow">↗</span></div></a><a class="service-tile" href="/bathroom-renovations">{picture('hero-alt','Illustrative premium interior design reference')}<div class="tile-overlay"><span class="service-number">03 / BATHROOMS</span><h3>Bathroom<br>renovations</h3><span class="circle-arrow">↗</span></div></a><a class="service-tile" href="/extensions">{picture('home-land-package','Illustrative residential home exterior and extension design')}<div class="tile-overlay"><span class="service-number">04 / EXTENSIONS</span><h3>Extensions &<br>additions</h3><span class="circle-arrow">↗</span></div></a></div><p class="image-note">Images are illustrative design references, not a portfolio of completed Milestone Renovate projects.</p><a class="text-link center-link" href="/services">All renovation services <span>↗</span></a></div></section>
<section class="section philosophy"><div class="wrap philosophy-grid"><div class="philosophy-media">{picture('hero-alt','Contemporary residential design concept with considered material palette')}<div class="media-stamp">DESIGN FOR<br><strong>EVERYDAY</strong><br>LIVING.</div></div><div class="philosophy-copy">{kicker('THE MILESTONE APPROACH')}<h2>Good renovations begin <em>before the first wall moves.</em></h2><p>We believe the best spaces are grounded in a real understanding of how you use them. That means asking the right questions, working through constraints, and keeping the big picture in view.</p><div class="principles"><div><b>01</b><div><h3>Understand first</h3><p>Your needs, your home, your budget priorities.</p></div></div><div><b>02</b><div><h3>Plan with purpose</h3><p>Layout, finishes and practical construction thinking.</p></div></div><div><b>03</b><div><h3>Deliver with care</h3><p>Attention to sequence, coordination and detail.</p></div></div></div><a class="text-link" href="/about">How we work <span>↗</span></a></div></div></section>
<section class="section inspirations"><div class="wrap">{split_header('LOOK CLOSER','A little inspiration.<br><em>A lot of possibility.</em>','A collection of architectural concepts and material ideas to help start a conversation about your space.')}<div class="inspo-grid"><a href="/inspiration" class="inspo-card">{picture('luxury-renovation','Open plan modern interior concept')}<span>01 / WARM MODERN LIVING</span></a><a href="/inspiration" class="inspo-card">{picture('dual-occupancy','Contemporary architectural materials and home facade concept')}<span>02 / ARCHITECTURAL CHARACTER</span></a><a href="/inspiration" class="inspo-card">{picture('hero','Luxury residential design concept')}<span>03 / CONNECTED SPACES</span></a></div></div></section>
<section class="section faq-section"><div class="wrap faq-grid"><div>{kicker('GOOD QUESTIONS, GOOD STARTS')}<h2>Wondering where<br><em>to begin?</em></h2><p>Every home is different. Here are a few starting points worth considering.</p></div><div class="faq-list"><details><summary>Can we renovate while living in the home?</summary><p>It depends on the scope. Some works can be staged while occupied, while significant renovation may require temporary arrangements. We can discuss practicality during planning.</p></details><details><summary>Do renovation projects require approvals?</summary><p>Some works may need council, strata or other approvals. Requirements depend on the location and nature of the work, especially structural or external changes.</p></details><details><summary>Can you help with planning and finishes?</summary><p>Yes, the enquiry process can start with your layout priorities, design preferences, material ideas and practical buildability questions.</p></details><details><summary>What should I prepare before getting in touch?</summary><p>Share your suburb, type of space, approximate budget and desired timeframe. Reference photos or a simple wish list can help start the conversation.</p></details></div></div></section>{cta()}'''

